/* =====================================================================
   Think&Eat - Tablas para Supabase (PostgreSQL)
   En Supabase: SQL Editor > New query > pegá este archivo > Run.
   Después hacé lo mismo con 02_datos.sql.
   ATENCIÓN: si las tablas ya existen, las borra y las vuelve a crear.
   ===================================================================== */

DROP TABLE IF EXISTS "RecetaPasos", "RecetaIngredientes", "Recetas", "Ingredientes", "Unidades", "CategoriasIngrediente" CASCADE;

CREATE TABLE "CategoriasIngrediente" (
  "Id"     integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Nombre" varchar(80) NOT NULL UNIQUE,
  "Emoji"  varchar(16),
  "Orden"  integer NOT NULL DEFAULT 0
);

CREATE TABLE "Unidades" (
  "Id"           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Nombre"       varchar(40) NOT NULL,
  "NombrePlural" varchar(40) NOT NULL,
  "Abreviatura"  varchar(20) NOT NULL UNIQUE,
  -- conteo: se cuenta (unidad, docena, diente...) / masa: gramos / volumen: ml / libre: a gusto
  "Tipo"         varchar(10) NOT NULL CHECK ("Tipo" IN ('conteo', 'masa', 'volumen', 'libre')),
  -- Equivalencia de 1 de esta unidad en la base de su tipo (unidades, gramos o ml)
  "FactorBase"   numeric(12,4) NOT NULL DEFAULT 1,
  "Orden"        integer NOT NULL DEFAULT 0
);

-- Los ingredientes base usan Id 1..999. Los que se crean desde la app arrancan en 1000.
CREATE TABLE "Ingredientes" (
  "Id"              integer GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY,
  "Nombre"          varchar(100) NOT NULL,
  "NombrePlural"    varchar(100),
  "CategoriaId"     integer NOT NULL REFERENCES "CategoriasIngrediente"("Id"),
  "Emoji"           varchar(16),
  "UnidadDefaultId" integer NOT NULL REFERENCES "Unidades"("Id"),
  -- Peso aproximado de 1 unidad mediana (o de 1 paquete, lata o atado)
  "PesoUnidadGr"    numeric(10,2),
  "TieneTamanio"    boolean NOT NULL DEFAULT false,
  -- Básico: sal, pimienta, aceite. Se asume que siempre hay.
  "EsBasico"        boolean NOT NULL DEFAULT false,
  "Sinonimos"       varchar(500),
  "BusquedaImagen"  varchar(150),
  "ImagenUrl"       varchar(600),
  "EsPersonalizado" boolean NOT NULL DEFAULT false,
  "FechaAlta"       timestamptz NOT NULL DEFAULT now()
);
-- Nombre único sin importar mayúsculas
CREATE UNIQUE INDEX "UQ_Ingredientes_Nombre" ON "Ingredientes" (lower("Nombre"));
CREATE INDEX "IX_Ingredientes_Categoria" ON "Ingredientes" ("CategoriaId");

CREATE TABLE "Recetas" (
  "Id"             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Nombre"         varchar(120) NOT NULL UNIQUE,
  "Descripcion"    varchar(400),
  "Categoria"      varchar(50) NOT NULL,
  "TiempoMin"      integer NOT NULL,
  "Dificultad"     varchar(20) NOT NULL CHECK ("Dificultad" IN ('Fácil', 'Media', 'Difícil')),
  "Porciones"      integer NOT NULL DEFAULT 4,
  "Emoji"          varchar(16),
  "Consejo"        varchar(600),
  "BusquedaImagen" varchar(150),
  "ImagenUrl"      varchar(600)
);

CREATE TABLE "RecetaIngredientes" (
  "Id"            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RecetaId"      integer NOT NULL REFERENCES "Recetas"("Id") ON DELETE CASCADE,
  "IngredienteId" integer NOT NULL REFERENCES "Ingredientes"("Id"),
  "Cantidad"      numeric(10,2),  -- NULL cuando la unidad es "a gusto"
  "UnidadId"      integer NOT NULL REFERENCES "Unidades"("Id"),
  "Tamanio"       varchar(10) CHECK ("Tamanio" IN ('chico', 'mediano', 'grande')),
  "Nota"          varchar(150),
  "EsOpcional"    boolean NOT NULL DEFAULT false,
  "Orden"         integer NOT NULL DEFAULT 0,
  UNIQUE ("RecetaId", "IngredienteId")
);
CREATE INDEX "IX_RecetaIngredientes_Ingrediente" ON "RecetaIngredientes" ("IngredienteId");

CREATE TABLE "RecetaPasos" (
  "Id"          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RecetaId"    integer NOT NULL REFERENCES "Recetas"("Id") ON DELETE CASCADE,
  "Numero"      integer NOT NULL,
  "Titulo"      varchar(100) NOT NULL,
  "Descripcion" text NOT NULL,
  "Minutos"     integer,
  UNIQUE ("RecetaId", "Numero")
);

/* Seguridad: Supabase expone las tablas del esquema public en su API pública.
   Activar RLS sin políticas bloquea ese acceso público; el backend de Node se
   conecta con el usuario dueño de las tablas, así que no lo afecta. */
ALTER TABLE "CategoriasIngrediente" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Unidades"              ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Ingredientes"          ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Recetas"               ENABLE ROW LEVEL SECURITY;
ALTER TABLE "RecetaIngredientes"    ENABLE ROW LEVEL SECURITY;
ALTER TABLE "RecetaPasos"           ENABLE ROW LEVEL SECURITY;
